solutions.naive:
class Solution:
    def intersect(self, nums1: list[int], nums2: list[int]) -> list[int]:
        used = [False] * len(nums2)
        ans = []
        for x in nums1:
            for i, y in enumerate(nums2):
                if not used[i] and x == y:
                    used[i] = True
                    ans.append(x)
                    break
        return ans

