class Solution:
    def intersect(self, nums1: list[int], nums2: list[int]) -> list[int]:
        if len(nums1) > len(nums2):
            nums1, nums2 = nums2, nums1
        counts = {}
        for x in nums1:
            counts[x] = counts.get(x, 0) + 1
        ans = []
        for x in nums2:
            if counts.get(x, 0) > 0:
                ans.append(x)
                counts[x] -= 1
        return ans

